"""Greedy word wrapping for plain text, keeping paragraph breaks."""


def wrap(text, width):
    """Wrap text to lines of at most width characters.

    Paragraphs are separated by blank lines and come out separated by exactly one empty line.
    Whitespace inside a paragraph collapses to single spaces. A word longer than width goes on
    a line of its own, unbroken; hyphenated words are not split.
    """
    if isinstance(width, bool) or not isinstance(width, int) or width < 1:
        raise ValueError(f"width must be an int of at least 1: {width!r}")
    paragraphs = []
    current = []
    for line in text.splitlines():
        if line.strip():
            current.append(line)
        elif current:
            paragraphs.append(current)
            current = []
    if current:
        paragraphs.append(current)
    out = []
    for lines in paragraphs:
        if out:
            out.append("")
        out.extend(_fill(" ".join(lines).split(), width))
    return "\n".join(out)


def _fill(words, width):
    """Pack words greedily into lines of at most width characters."""
    lines = []
    line = ""
    for word in words:
        if not line:
            line = word
        elif len(line) + 1 + len(word) <= width:
            line += " " + word
        else:
            lines.append(line)
            line = word
    if line:
        lines.append(line)
    return lines

