import unittest

from tests.test_cli import run
from textkit.wrap import wrap


class WrapTest(unittest.TestCase):
    def test_fills_greedily(self):
        self.assertEqual(wrap("aaa bbb ccc", 7), "aaa bbb\nccc")

    def test_exact_fit_stays_on_one_line(self):
        self.assertEqual(wrap("aaa bbb", 7), "aaa bbb")

    def test_long_word_gets_its_own_line_unbroken(self):
        self.assertEqual(wrap("a verylongword b", 5), "a\nverylongword\nb")
        self.assertEqual(wrap("verylongword", 3), "verylongword")

    def test_hyphenated_words_are_not_split(self):
        self.assertEqual(wrap("well-known thing", 6), "well-known\nthing")

    def test_newlines_inside_a_paragraph_collapse_to_spaces(self):
        self.assertEqual(wrap("aa\nbb  cc\t dd", 20), "aa bb cc dd")

    def test_paragraphs_are_separated_by_one_blank_line(self):
        self.assertEqual(wrap("one two\n\n\nthree\n   \nfour", 20), "one two\n\nthree\n\nfour")

    def test_crlf_line_endings(self):
        self.assertEqual(wrap("aa\r\nbb\r\n\r\ncc", 20), "aa bb\n\ncc")

    def test_no_leading_or_trailing_blank_lines(self):
        self.assertEqual(wrap("\n\n  \nhi there\n\n\n", 20), "hi there")

    def test_empty_or_blank_text(self):
        self.assertEqual(wrap("", 10), "")
        self.assertEqual(wrap(" \n\t\n", 10), "")

    def test_width_below_one_raises(self):
        for bad in [0, -1]:
            with self.subTest(width=bad), self.assertRaises(ValueError):
                wrap("abc", bad)

    def test_non_int_width_raises(self):
        for bad in [2.5, "7", None, True]:
            with self.subTest(width=bad), self.assertRaises(ValueError):
                wrap("abc", bad)


class WrapCommandTest(unittest.TestCase):
    def test_width_option(self):
        self.assertEqual(run("wrap", "aaa bbb ccc", "--width", "7"), (0, "aaa bbb\nccc\n", ""))

    def test_default_width_is_40(self):
        words = " ".join(["word"] * 9)  # the first 8 words fill 39 characters; 9 would be 44
        self.assertEqual(run("wrap", words), (0, "word word word word word word word word\nword\n", ""))

    def test_paragraphs_through_the_command(self):
        self.assertEqual(run("wrap", "one\n\ntwo", "--width", "10"), (0, "one\n\ntwo\n", ""))

    def test_zero_width_reports_error(self):
        code, out, err = run("wrap", "x", "--width", "0")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "), err)


if __name__ == "__main__":
    unittest.main()

